def stripe_api_post(path: str, fields: list[tuple[str, str]]) -> dict:








    if not STRIPE_SECRET_KEY:








        raise HTTPException(








            status_code=503,








            detail="Stripe is not configured. Add ANYAICAM_STRIPE_SECRET_KEY.",








        )

















    body = urlencode(fields).encode("utf-8")








    request = UrlRequest(








        f"{STRIPE_API_BASE}{path}",








        data=body,








        method="POST",








        headers={








            "Authorization": f"Bearer {STRIPE_SECRET_KEY}",








            "Content-Type": "application/x-www-form-urlencoded",








            "User-Agent": f"AnyAiCam-VMS/{APP_VERSION}",








        },








    )








    try:








        with urlopen(request, timeout=20) as response:








            return json.loads(response.read().decode("utf-8"))








    except HTTPError as exc:








        payload = exc.read().decode("utf-8", errors="replace")








        try:








            error_data = json.loads(payload)








            message = (








                error_data.get("error", {}).get("message")








                or "Stripe request failed."








            )








        except json.JSONDecodeError:








            message = "Stripe request failed."








        structured_log(








            "stripe.api_error",








            level="error",








            status_code=exc.code,








            path=path,








            message=message,








        )








        raise HTTPException(status_code=502, detail=message) from exc








    except (URLError, TimeoutError, OSError) as exc:








        structured_log(








            "stripe.network_error",








            level="error",








            path=path,








            error=str(exc),








        )








        raise HTTPException(








            status_code=502,








            detail="Could not connect to Stripe.",








        ) from exc


























def parse_stripe_signature(header_value: str) -> tuple[int, list[str]]:








    timestamp = 0








    signatures = []








    for part in str(header_value or "").split(","):








        key, separator, value = part.strip().partition("=")








        if not separator:








            continue








        if key == "t":








            try:








                timestamp = int(value)








            except ValueError:








                timestamp = 0








        elif key == "v1":








            signatures.append(value)








    return timestamp, signatures


























def verify_stripe_webhook_signature(








    payload: bytes,








    signature_header: str,








) -> bool:








    if not STRIPE_WEBHOOK_SECRET:








        return False

















    timestamp, signatures = parse_stripe_signature(signature_header)








    if not timestamp or not signatures:








        return False

















    if abs(int(time.time()) - timestamp) > STRIPE_WEBHOOK_TOLERANCE_SECONDS:








        return False

















    signed_payload = (








        str(timestamp).encode("utf-8")








        + b"."








        + payload








    )








    expected = hmac.new(








        STRIPE_WEBHOOK_SECRET.encode("utf-8"),








        signed_payload,








        hashlib.sha256,








    ).hexdigest()








    return any(








        hmac.compare_digest(expected, signature)








        for signature in signatures








    )


























