@app.middleware("http")








async def forwarded_https_middleware(request: Request, call_next):








    forwarded_proto = (








        request.headers.get("x-forwarded-proto", request.url.scheme)








        if TRUST_PROXY_HEADERS else request.url.scheme








    )








    if (








        FORCE_HTTPS








        and forwarded_proto != "https"








        and request.url.path not in {"/health", "/ready", "/version"}








    ):








        host = request.headers.get("x-forwarded-host") or request.headers.get("host")








        if host:








            secure_url = f"https://{host}{request.url.path}"








            if request.url.query:








                secure_url += f"?{request.url.query}"








            return RedirectResponse(secure_url, status_code=307)

















    response = await call_next(request)








    # Live playlists are rewritten every second and reference a three-segment
    # rolling window. Reusing an old manifest makes the player request
    # segments that FFmpeg has already deleted.
    if request.url.path.startswith(f"{HLS_URL_PREFIX}/"):
        response.headers["Cache-Control"] = HLS_CACHE_CONTROL
        response.headers["CDN-Cache-Control"] = "no-store"
        response.headers["Pragma"] = "no-cache"
        response.headers["Expires"] = "0"

    if forwarded_proto == "https":








        response.headers.setdefault(








            "Strict-Transport-Security",








            "max-age=31536000; includeSubDomains",








        )








    response.headers.setdefault("X-Content-Type-Options", "nosniff")








    response.headers.setdefault("Referrer-Policy", "strict-origin-when-cross-origin")








    response.headers.setdefault(








        "Permissions-Policy", "camera=(), microphone=(), geolocation=()"








    )








    return response








