# ============================================================================
# Phase 6H — Controlled Rollout Governance and Launch Readiness
# Approval-gated rollout planning, staged cohorts, launch windows, and formal
# rollback checkpoints. No automatic rollout or provider activation occurs.
# ============================================================================

PHASE6H_MARKER = "Phase 6H — Controlled Rollout Governance and Launch Readiness"
PHASE6H_PLANS_FILE = RECORDINGS_FOLDER / "phase6h_rollout_plans.json"
PHASE6H_APPROVALS_FILE = RECORDINGS_FOLDER / "phase6h_rollout_approvals.json"
PHASE6H_CHECKPOINTS_FILE = RECORDINGS_FOLDER / "phase6h_rollout_checkpoints.json"
PHASE6H_EVENTS_FILE = RECORDINGS_FOLDER / "phase6h_rollout_events.json"

PHASE6H_MAX_STAGE_PERCENT = float(os.environ.get("PHASE6H_MAX_STAGE_PERCENT", "25"))
PHASE6H_REQUIRED_APPROVALS = int(os.environ.get("PHASE6H_REQUIRED_APPROVALS", "2"))
PHASE6H_MAX_ACTIVE_STAGE = int(os.environ.get("PHASE6H_MAX_ACTIVE_STAGE", "1"))


class Phase6HRolloutPlanModel(BaseModel):
    name: str = Field(min_length=3, max_length=160)
    owner: str = Field(min_length=2, max_length=120)
    pilot_id: str = Field(min_length=2, max_length=120)
    total_customers: int = Field(ge=1, le=1000000)
    stages: list[int] = Field(min_length=1, max_length=20)
    rollback_trigger: str = Field(min_length=5, max_length=3000)
    maintenance_window: str = Field(min_length=3, max_length=300)
    notes: str = Field(default="", max_length=4000)


class Phase6HRolloutApprovalModel(BaseModel):
    decision: str = Field(pattern="^(approved|rejected|revoked)$")
    approver: str = Field(min_length=2, max_length=120)
    role: str = Field(min_length=2, max_length=120)
    notes: str = Field(default="", max_length=2000)


class Phase6HCheckpointModel(BaseModel):
    stage_number: int = Field(ge=1, le=100)
    status: str = Field(pattern="^(pending|ready|active|paused|completed|rolled_back|cancelled)$")
    success_rate: float = Field(default=0, ge=0, le=100)
    error_rate: float = Field(default=0, ge=0, le=100)
    notes: str = Field(default="", max_length=3000)


def _phase6h_load(path: Path, default):
    value = load_json_file(path, default)
    return value if isinstance(value, type(default)) else default


def _phase6h_save(path: Path, value) -> None:
    save_json_file(path, value)


def phase6h_plan_by_id(plan_id: str) -> dict | None:
    return next(
        (item for item in _phase6h_load(PHASE6H_PLANS_FILE, []) if item.get("id") == plan_id),
        None,
    )


def phase6h_append_event(plan_id: str, event: str, actor: str, details: str = "") -> dict:
    item = {
        "id": uuid.uuid4().hex[:16],
        "plan_id": plan_id,
        "event": event,
        "actor": actor,
        "details": details[:2000],
        "created_at": datetime.now().isoformat(),
    }
    events = _phase6h_load(PHASE6H_EVENTS_FILE, [])
    events.append(item)
    _phase6h_save(PHASE6H_EVENTS_FILE, events[-10000:])
    structured_log("phase6h.rollout_event", plan_id=plan_id, event=event, actor=actor)
    return item


def phase6h_plan_readiness(plan: dict) -> dict:
    pilot_id = plan.get("pilot_id")
    pilot = phase6f_pilot_by_id(pilot_id)
    reviews = [
        item for item in _phase6g_load(PHASE6G_REVIEWS_FILE, [])
        if item.get("pilot_id") == pilot_id
    ]
    decisions = [
        item for item in _phase6g_load(PHASE6G_DECISIONS_FILE, [])
        if item.get("pilot_id") == pilot_id
    ]
    latest_review = reviews[-1] if reviews else None
    latest_decision = decisions[-1] if decisions else None

    approvals = [
        item for item in _phase6h_load(PHASE6H_APPROVALS_FILE, [])
        if item.get("plan_id") == plan.get("id")
    ]
    active_approvals = {}
    for item in approvals:
        key = (item.get("approver", "").lower(), item.get("role", "").lower())
        if item.get("decision") == "approved":
            active_approvals[key] = item
        elif item.get("decision") in {"rejected", "revoked"}:
            active_approvals.pop(key, None)

    stages = plan.get("stages") or []
    stage_sum = sum(stages)
    max_stage = max(stages) if stages else 0
    blockers = []

    if not pilot:
        blockers.append("Referenced pilot does not exist.")
    if not latest_review or latest_review.get("recommendation") != "go":
        blockers.append("Latest Phase 6G outcome review is not GO.")
    if not latest_decision or latest_decision.get("decision") != "go":
        blockers.append("Formal Phase 6G GO decision is missing.")
    if len(active_approvals) < PHASE6H_REQUIRED_APPROVALS:
        blockers.append(f"{PHASE6H_REQUIRED_APPROVALS} rollout approvals are required.")
    if stage_sum != 100:
        blockers.append("Rollout stage percentages must total 100.")
    if max_stage > PHASE6H_MAX_STAGE_PERCENT:
        blockers.append(
            f"No rollout stage may exceed {PHASE6H_MAX_STAGE_PERCENT:g}%."
        )
    if not plan.get("rollback_trigger"):
        blockers.append("Rollback trigger is required.")
    if not plan.get("maintenance_window"):
        blockers.append("Maintenance window is required.")

    return {
        "plan_id": plan.get("id"),
        "ready": not blockers,
        "pilot_id": pilot_id,
        "active_approval_count": len(active_approvals),
        "required_approval_count": PHASE6H_REQUIRED_APPROVALS,
        "stage_total_percent": stage_sum,
        "largest_stage_percent": max_stage,
        "latest_review_recommendation": latest_review.get("recommendation") if latest_review else None,
        "latest_launch_decision": latest_decision.get("decision") if latest_decision else None,
        "blockers": blockers,
        "automatic_rollout_performed": False,
    }


@app.get("/api/rollouts")
def phase6h_list_rollouts(request: Request) -> dict:
    user = current_user(request)
    if not has_permission(user, "manage_settings"):
        raise HTTPException(status_code=403, detail="Settings permission is required.")
    plans = _phase6h_load(PHASE6H_PLANS_FILE, [])
    return {
        "rollouts": [
            {**item, "readiness": phase6h_plan_readiness(item)}
            for item in reversed(plans[-500:])
        ]
    }


@app.post("/api/rollouts")
def phase6h_create_rollout(payload: Phase6HRolloutPlanModel, request: Request) -> dict:
    user = current_user(request)
    if not has_permission(user, "manage_settings"):
        raise HTTPException(status_code=403, detail="Settings permission is required.")
    if sum(payload.stages) != 100:
        raise HTTPException(status_code=400, detail="Rollout stages must total 100 percent.")
    if max(payload.stages) > PHASE6H_MAX_STAGE_PERCENT:
        raise HTTPException(
            status_code=400,
            detail=f"Each rollout stage is limited to {PHASE6H_MAX_STAGE_PERCENT:g} percent.",
        )
    if not phase6f_pilot_by_id(payload.pilot_id):
        raise HTTPException(status_code=404, detail="Pilot not found.")

    now = datetime.now().isoformat()
    plan = {
        "id": uuid.uuid4().hex[:16],
        "name": payload.name.strip(),
        "owner": payload.owner.strip(),
        "pilot_id": payload.pilot_id.strip(),
        "total_customers": payload.total_customers,
        "stages": payload.stages,
        "rollback_trigger": payload.rollback_trigger.strip(),
        "maintenance_window": payload.maintenance_window.strip(),
        "notes": payload.notes.strip(),
        "status": "draft",
        "current_stage": 0,
        "created_at": now,
        "updated_at": now,
        "created_by": user.get("id", "unknown"),
    }
    plans = _phase6h_load(PHASE6H_PLANS_FILE, [])
    plans.append(plan)
    _phase6h_save(PHASE6H_PLANS_FILE, plans[-2000:])
    phase6h_append_event(plan["id"], "rollout_plan_created", user.get("id", "unknown"))
    return {
        "status": "complete",
        "message": "Rollout plan created in draft status.",
        "plan": plan,
        "readiness": phase6h_plan_readiness(plan),
        "external_action_performed": False,
    }


@app.post("/api/rollouts/{plan_id}/approvals")
def phase6h_approval(plan_id: str, payload: Phase6HRolloutApprovalModel, request: Request) -> dict:
    user = current_user(request)
    if not has_permission(user, "manage_settings"):
        raise HTTPException(status_code=403, detail="Settings permission is required.")
    plan = phase6h_plan_by_id(plan_id)
    if not plan:
        raise HTTPException(status_code=404, detail="Rollout plan not found.")
    item = {
        "id": uuid.uuid4().hex[:16],
        "plan_id": plan_id,
        "decision": payload.decision,
        "approver": payload.approver.strip(),
        "role": payload.role.strip(),
        "notes": payload.notes.strip(),
        "recorded_by": user.get("id", "unknown"),
        "created_at": datetime.now().isoformat(),
    }
    approvals = _phase6h_load(PHASE6H_APPROVALS_FILE, [])
    approvals.append(item)
    _phase6h_save(PHASE6H_APPROVALS_FILE, approvals[-10000:])
    phase6h_append_event(plan_id, f"approval_{payload.decision}", user.get("id", "unknown"))
    return {"status": "complete", "approval": item, "readiness": phase6h_plan_readiness(plan)}


@app.post("/api/rollouts/{plan_id}/checkpoints")
def phase6h_checkpoint(plan_id: str, payload: Phase6HCheckpointModel, request: Request) -> dict:
    user = current_user(request)
    if not has_permission(user, "manage_settings"):
        raise HTTPException(status_code=403, detail="Settings permission is required.")
    plan = phase6h_plan_by_id(plan_id)
    if not plan:
        raise HTTPException(status_code=404, detail="Rollout plan not found.")
    if payload.stage_number > len(plan.get("stages") or []):
        raise HTTPException(status_code=400, detail="Stage number exceeds rollout plan.")
    if payload.status in {"ready", "active"} and not phase6h_plan_readiness(plan)["ready"]:
        raise HTTPException(status_code=409, detail="Rollout readiness blockers remain.")

    item = {
        "id": uuid.uuid4().hex[:16],
        "plan_id": plan_id,
        "stage_number": payload.stage_number,
        "stage_percent": plan["stages"][payload.stage_number - 1],
        "status": payload.status,
        "success_rate": payload.success_rate,
        "error_rate": payload.error_rate,
        "notes": payload.notes.strip(),
        "recorded_by": user.get("id", "unknown"),
        "created_at": datetime.now().isoformat(),
        "external_action_performed": False,
    }
    records = _phase6h_load(PHASE6H_CHECKPOINTS_FILE, [])
    records.append(item)
    _phase6h_save(PHASE6H_CHECKPOINTS_FILE, records[-20000:])
    phase6h_append_event(
        plan_id, f"checkpoint_{payload.status}", user.get("id", "unknown"),
        f"stage={payload.stage_number}"
    )
    return {
        "status": "complete",
        "checkpoint": item,
        "automatic_rollout_performed": False,
    }


