# ============================================================================
# Phase 6I — Rollout Observation, Exception Control, and Post-Launch Assurance
# Local operational records only. No automatic deployment, rollback, customer
# activation, or external provider action is performed.
# ============================================================================

PHASE6I_MARKER = "Phase 6I — Rollout Observation, Exception Control, and Post-Launch Assurance"
PHASE6I_OBSERVATIONS_FILE = RECORDINGS_FOLDER / "phase6i_rollout_observations.json"
PHASE6I_EXCEPTIONS_FILE = RECORDINGS_FOLDER / "phase6i_rollout_exceptions.json"
PHASE6I_ASSURANCE_FILE = RECORDINGS_FOLDER / "phase6i_post_launch_assurance.json"
PHASE6I_SIGNOFFS_FILE = RECORDINGS_FOLDER / "phase6i_assurance_signoffs.json"

PHASE6I_MAX_ERROR_RATE = float(os.environ.get("PHASE6I_MAX_ERROR_RATE", "2.0"))
PHASE6I_MIN_SUCCESS_RATE = float(os.environ.get("PHASE6I_MIN_SUCCESS_RATE", "98.0"))
PHASE6I_MIN_AVAILABILITY = float(os.environ.get("PHASE6I_MIN_AVAILABILITY", "99.0"))
PHASE6I_REQUIRED_SIGNOFFS = int(os.environ.get("PHASE6I_REQUIRED_SIGNOFFS", "2"))


class Phase6IObservationModel(BaseModel):
    stage_number: int = Field(ge=1, le=100)
    success_rate: float = Field(ge=0, le=100)
    error_rate: float = Field(ge=0, le=100)
    availability: float = Field(ge=0, le=100)
    customer_count: int = Field(ge=0, le=1000000)
    notes: str = Field(default="", max_length=3000)


class Phase6IExceptionModel(BaseModel):
    severity: str = Field(pattern="^(low|medium|high|critical)$")
    category: str = Field(min_length=2, max_length=120)
    summary: str = Field(min_length=5, max_length=1000)
    owner: str = Field(min_length=2, max_length=120)
    containment: str = Field(default="", max_length=3000)


class Phase6IExceptionStatusModel(BaseModel):
    status: str = Field(pattern="^(open|contained|resolved|accepted)$")
    notes: str = Field(default="", max_length=3000)


class Phase6ISignoffModel(BaseModel):
    decision: str = Field(pattern="^(approved|rejected|revoked)$")
    approver: str = Field(min_length=2, max_length=120)
    role: str = Field(min_length=2, max_length=120)
    notes: str = Field(default="", max_length=3000)


def _phase6i_load(path: Path, default):
    value = load_json_file(path, default)
    return value if isinstance(value, type(default)) else default


def _phase6i_save(path: Path, value) -> None:
    save_json_file(path, value)


def phase6i_rollout_assurance(plan_id: str) -> dict:
    plan = phase6h_plan_by_id(plan_id)
    if not plan:
        raise HTTPException(status_code=404, detail="Rollout plan not found.")

    observations = [
        item for item in _phase6i_load(PHASE6I_OBSERVATIONS_FILE, [])
        if item.get("plan_id") == plan_id
    ]
    exceptions = [
        item for item in _phase6i_load(PHASE6I_EXCEPTIONS_FILE, [])
        if item.get("plan_id") == plan_id
    ]
    signoffs = [
        item for item in _phase6i_load(PHASE6I_SIGNOFFS_FILE, [])
        if item.get("plan_id") == plan_id
    ]

    active_signoffs = {}
    for item in signoffs:
        key = (item.get("approver", "").lower(), item.get("role", "").lower())
        if item.get("decision") == "approved":
            active_signoffs[key] = item
        elif item.get("decision") in {"rejected", "revoked"}:
            active_signoffs.pop(key, None)

    latest_by_stage = {}
    for item in observations:
        latest_by_stage[item.get("stage_number")] = item

    active_exceptions = [
        item for item in exceptions
        if item.get("status", "open") not in {"resolved", "accepted"}
    ]
    critical_exceptions = [
        item for item in active_exceptions if item.get("severity") == "critical"
    ]

    failed_stages = []
    for stage, item in latest_by_stage.items():
        if (
            float(item.get("success_rate", 0)) < PHASE6I_MIN_SUCCESS_RATE
            or float(item.get("error_rate", 100)) > PHASE6I_MAX_ERROR_RATE
            or float(item.get("availability", 0)) < PHASE6I_MIN_AVAILABILITY
        ):
            failed_stages.append(stage)

    blockers = []
    if not observations:
        blockers.append("No rollout observations have been recorded.")
    if failed_stages:
        blockers.append(f"Stages outside assurance thresholds: {sorted(failed_stages)}.")
    if critical_exceptions:
        blockers.append("Critical rollout exceptions remain unresolved.")
    if len(active_signoffs) < PHASE6I_REQUIRED_SIGNOFFS:
        blockers.append(f"{PHASE6I_REQUIRED_SIGNOFFS} assurance signoffs are required.")

    completed_stages = len({
        item.get("stage_number")
        for item in observations
        if item.get("status") == "completed"
    })
    expected_stages = len(plan.get("stages") or [])
    if completed_stages < expected_stages:
        blockers.append(
            f"Only {completed_stages} of {expected_stages} rollout stages are marked completed."
        )

    result = {
        "id": uuid.uuid4().hex[:16],
        "plan_id": plan_id,
        "checked_at": datetime.now().isoformat(),
        "assured": not blockers,
        "observation_count": len(observations),
        "active_exception_count": len(active_exceptions),
        "critical_exception_count": len(critical_exceptions),
        "active_signoff_count": len(active_signoffs),
        "required_signoff_count": PHASE6I_REQUIRED_SIGNOFFS,
        "completed_stage_count": completed_stages,
        "expected_stage_count": expected_stages,
        "failed_stages": sorted(failed_stages),
        "blockers": blockers,
        "automatic_action_performed": False,
    }
    records = _phase6i_load(PHASE6I_ASSURANCE_FILE, [])
    records.append(result)
    _phase6i_save(PHASE6I_ASSURANCE_FILE, records[-5000:])
    structured_log(
        "phase6i.assurance_review",
        plan_id=plan_id,
        assured=result["assured"],
        blocker_count=len(blockers),
    )
    return result


@app.post("/api/rollouts/{plan_id}/observations")
def phase6i_observation(plan_id: str, payload: Phase6IObservationModel, request: Request) -> dict:
    user = current_user(request)
    if not has_permission(user, "manage_settings"):
        raise HTTPException(status_code=403, detail="Settings permission is required.")
    plan = phase6h_plan_by_id(plan_id)
    if not plan:
        raise HTTPException(status_code=404, detail="Rollout plan not found.")
    if payload.stage_number > len(plan.get("stages") or []):
        raise HTTPException(status_code=400, detail="Stage number exceeds rollout plan.")

    status = "completed"
    if (
        payload.success_rate < PHASE6I_MIN_SUCCESS_RATE
        or payload.error_rate > PHASE6I_MAX_ERROR_RATE
        or payload.availability < PHASE6I_MIN_AVAILABILITY
    ):
        status = "attention_required"

    item = {
        "id": uuid.uuid4().hex[:16],
        "plan_id": plan_id,
        "stage_number": payload.stage_number,
        "success_rate": payload.success_rate,
        "error_rate": payload.error_rate,
        "availability": payload.availability,
        "customer_count": payload.customer_count,
        "notes": payload.notes.strip(),
        "status": status,
        "recorded_by": user.get("id", "unknown"),
        "created_at": datetime.now().isoformat(),
        "external_action_performed": False,
    }
    records = _phase6i_load(PHASE6I_OBSERVATIONS_FILE, [])
    records.append(item)
    _phase6i_save(PHASE6I_OBSERVATIONS_FILE, records[-30000:])
    phase6h_append_event(
        plan_id,
        "observation_recorded",
        user.get("id", "unknown"),
        f"stage={payload.stage_number};status={status}",
    )
    return {"status": "complete", "observation": item}


