@app.put("/api/rollouts/{plan_id}/exceptions/{exception_id}")
def phase6i_exception_status(
    plan_id: str,
    exception_id: str,
    payload: Phase6IExceptionStatusModel,
    request: Request,
) -> dict:
    user = current_user(request)
    if not has_permission(user, "manage_settings"):
        raise HTTPException(status_code=403, detail="Settings permission is required.")

    records = _phase6i_load(PHASE6I_EXCEPTIONS_FILE, [])
    item = next(
        (
            entry for entry in records
            if entry.get("id") == exception_id and entry.get("plan_id") == plan_id
        ),
        None,
    )
    if not item:
        raise HTTPException(status_code=404, detail="Rollout exception not found.")

    item["status"] = payload.status
    item["resolution_notes"] = payload.notes.strip()
    item["updated_at"] = datetime.now().isoformat()
    item["updated_by"] = user.get("id", "unknown")
    _phase6i_save(PHASE6I_EXCEPTIONS_FILE, records)
    phase6h_append_event(
        plan_id,
        f"exception_{payload.status}",
        user.get("id", "unknown"),
        exception_id,
    )
    return {"status": "complete", "exception": item}


