# ============================================================================
# Phase 6J — Service Transition, SLA Governance, and Operational Handoff
# Local governance records only. No automatic ticketing, paging, deployment,
# provider activation, or customer communication is performed.
# ============================================================================

PHASE6J_MARKER = "Phase 6J — Service Transition, SLA Governance, and Operational Handoff"
PHASE6J_SERVICES_FILE = RECORDINGS_FOLDER / "phase6j_service_registry.json"
PHASE6J_SLA_FILE = RECORDINGS_FOLDER / "phase6j_sla_policies.json"
PHASE6J_HANDOFFS_FILE = RECORDINGS_FOLDER / "phase6j_operational_handoffs.json"
PHASE6J_ESCALATIONS_FILE = RECORDINGS_FOLDER / "phase6j_escalation_matrix.json"
PHASE6J_REVIEWS_FILE = RECORDINGS_FOLDER / "phase6j_transition_reviews.json"

PHASE6J_REQUIRED_HANDOFFS = int(os.environ.get("PHASE6J_REQUIRED_HANDOFFS", "2"))
PHASE6J_MAX_P1_RESPONSE_MINUTES = int(os.environ.get("PHASE6J_MAX_P1_RESPONSE_MINUTES", "15"))
PHASE6J_MAX_P2_RESPONSE_MINUTES = int(os.environ.get("PHASE6J_MAX_P2_RESPONSE_MINUTES", "60"))
PHASE6J_MIN_AVAILABILITY_TARGET = float(os.environ.get("PHASE6J_MIN_AVAILABILITY_TARGET", "99.0"))


class Phase6JServiceModel(BaseModel):
    name: str = Field(min_length=3, max_length=160)
    owner: str = Field(min_length=2, max_length=120)
    description: str = Field(default="", max_length=3000)
    support_hours: str = Field(min_length=3, max_length=200)
    customer_scope: str = Field(min_length=2, max_length=1000)
    dependencies: list[str] = Field(default_factory=list, max_length=50)


class Phase6JSLAModel(BaseModel):
    availability_target: float = Field(ge=0, le=100)
    p1_response_minutes: int = Field(ge=1, le=10080)
    p2_response_minutes: int = Field(ge=1, le=10080)
    restoration_target_minutes: int = Field(ge=1, le=10080)
    measurement_window: str = Field(min_length=2, max_length=120)
    exclusions: list[str] = Field(default_factory=list, max_length=50)


class Phase6JHandoffModel(BaseModel):
    role: str = Field(min_length=2, max_length=120)
    owner: str = Field(min_length=2, max_length=120)
    decision: str = Field(pattern="^(accepted|rejected|revoked)$")
    runbook_verified: bool
    access_verified: bool
    training_verified: bool
    notes: str = Field(default="", max_length=3000)


class Phase6JEscalationModel(BaseModel):
    severity: str = Field(pattern="^(p1|p2|p3|p4)$")
    primary_contact: str = Field(min_length=2, max_length=160)
    secondary_contact: str = Field(default="", max_length=160)
    response_minutes: int = Field(ge=1, le=10080)
    communication_channel: str = Field(min_length=2, max_length=160)
    notes: str = Field(default="", max_length=2000)


def _phase6j_load(path: Path, default):
    value = load_json_file(path, default)
    return value if isinstance(value, type(default)) else default


def _phase6j_save(path: Path, value) -> None:
    save_json_file(path, value)


def phase6j_service_by_id(service_id: str) -> dict | None:
    return next(
        (
            item for item in _phase6j_load(PHASE6J_SERVICES_FILE, [])
            if item.get("id") == service_id
        ),
        None,
    )


def phase6j_transition_review(service_id: str) -> dict:
    service = phase6j_service_by_id(service_id)
    if not service:
        raise HTTPException(status_code=404, detail="Service record not found.")

    sla_records = [
        item for item in _phase6j_load(PHASE6J_SLA_FILE, [])
        if item.get("service_id") == service_id
    ]
    handoffs = [
        item for item in _phase6j_load(PHASE6J_HANDOFFS_FILE, [])
        if item.get("service_id") == service_id
    ]
    escalations = [
        item for item in _phase6j_load(PHASE6J_ESCALATIONS_FILE, [])
        if item.get("service_id") == service_id
    ]

    latest_sla = sla_records[-1] if sla_records else None

    active_handoffs = {}
    for item in handoffs:
        key = (item.get("owner", "").lower(), item.get("role", "").lower())
        if item.get("decision") == "accepted":
            active_handoffs[key] = item
        elif item.get("decision") in {"rejected", "revoked"}:
            active_handoffs.pop(key, None)

    latest_escalations = {}
    for item in escalations:
        latest_escalations[item.get("severity")] = item

    blockers = []
    if not latest_sla:
        blockers.append("SLA policy has not been recorded.")
    else:
        if float(latest_sla.get("availability_target", 0)) < PHASE6J_MIN_AVAILABILITY_TARGET:
            blockers.append("Availability target is below the Phase 6J minimum.")
        if int(latest_sla.get("p1_response_minutes", 999999)) > PHASE6J_MAX_P1_RESPONSE_MINUTES:
            blockers.append("P1 response time exceeds the Phase 6J maximum.")
        if int(latest_sla.get("p2_response_minutes", 999999)) > PHASE6J_MAX_P2_RESPONSE_MINUTES:
            blockers.append("P2 response time exceeds the Phase 6J maximum.")

    if len(active_handoffs) < PHASE6J_REQUIRED_HANDOFFS:
        blockers.append(f"{PHASE6J_REQUIRED_HANDOFFS} accepted operational handoffs are required.")

    for key, item in active_handoffs.items():
        if not (
            item.get("runbook_verified")
            and item.get("access_verified")
            and item.get("training_verified")
        ):
            blockers.append(
                f"Handoff verification is incomplete for {item.get('owner', 'unknown')}."
            )

    for severity in ("p1", "p2"):
        if severity not in latest_escalations:
            blockers.append(f"Escalation contact is missing for {severity.upper()}.")

    assurance_records = _phase6i_load(PHASE6I_ASSURANCE_FILE, [])
    latest_assurance = next(
        (
            item for item in reversed(assurance_records)
            if item.get("assured") is True
        ),
        None,
    )
    if not latest_assurance:
        blockers.append("No successful Phase 6I assurance review is available.")

    review = {
        "id": uuid.uuid4().hex[:16],
        "service_id": service_id,
        "checked_at": datetime.now().isoformat(),
        "transition_ready": not blockers,
        "service": service,
        "latest_sla": latest_sla,
        "accepted_handoff_count": len(active_handoffs),
        "required_handoff_count": PHASE6J_REQUIRED_HANDOFFS,
        "escalation_severities": sorted(latest_escalations.keys()),
        "phase6i_assurance_reference": latest_assurance.get("id") if latest_assurance else None,
        "blockers": blockers,
        "automatic_action_performed": False,
    }
    reviews = _phase6j_load(PHASE6J_REVIEWS_FILE, [])
    reviews.append(review)
