# ============================================================================
# Phase 6K — Service Performance, Renewal Readiness, and Continuous Improvement
# Local governance records only. No automatic billing, renewal, customer
# communication, deployment, or external provider action is performed.
# ============================================================================

PHASE6K_MARKER = "Phase 6K — Service Performance, Renewal Readiness, and Continuous Improvement"
PHASE6K_SCORECARDS_FILE = RECORDINGS_FOLDER / "phase6k_service_scorecards.json"
PHASE6K_ACTIONS_FILE = RECORDINGS_FOLDER / "phase6k_improvement_actions.json"
PHASE6K_RENEWALS_FILE = RECORDINGS_FOLDER / "phase6k_renewal_reviews.json"
PHASE6K_SIGNOFFS_FILE = RECORDINGS_FOLDER / "phase6k_renewal_signoffs.json"
PHASE6K_EVENTS_FILE = RECORDINGS_FOLDER / "phase6k_continuous_improvement_events.json"

PHASE6K_MIN_AVAILABILITY = float(os.environ.get("PHASE6K_MIN_AVAILABILITY", "99.0"))
PHASE6K_MIN_CUSTOMER_SCORE = float(os.environ.get("PHASE6K_MIN_CUSTOMER_SCORE", "4.0"))
PHASE6K_MAX_OPEN_CRITICAL_ACTIONS = int(os.environ.get("PHASE6K_MAX_OPEN_CRITICAL_ACTIONS", "0"))
PHASE6K_REQUIRED_RENEWAL_SIGNOFFS = int(os.environ.get("PHASE6K_REQUIRED_RENEWAL_SIGNOFFS", "2"))


class Phase6KScorecardModel(BaseModel):
    period_start: str = Field(min_length=8, max_length=40)
    period_end: str = Field(min_length=8, max_length=40)
    availability: float = Field(ge=0, le=100)
    incident_count: int = Field(ge=0, le=1000000)
    sla_breach_count: int = Field(ge=0, le=1000000)
    customer_score: float = Field(ge=1, le=5)
    support_ticket_count: int = Field(ge=0, le=1000000)
    notes: str = Field(default="", max_length=4000)


class Phase6KActionModel(BaseModel):
    title: str = Field(min_length=3, max_length=200)
    owner: str = Field(min_length=2, max_length=120)
    priority: str = Field(pattern="^(low|medium|high|critical)$")
    due_date: str = Field(min_length=8, max_length=40)
    success_measure: str = Field(min_length=3, max_length=1000)
    notes: str = Field(default="", max_length=3000)


class Phase6KActionStatusModel(BaseModel):
    status: str = Field(pattern="^(open|in_progress|blocked|completed|cancelled)$")
    notes: str = Field(default="", max_length=3000)


class Phase6KRenewalSignoffModel(BaseModel):
    decision: str = Field(pattern="^(approved|rejected|revoked)$")
    approver: str = Field(min_length=2, max_length=120)
    role: str = Field(min_length=2, max_length=120)
    notes: str = Field(default="", max_length=3000)


def _phase6k_load(path: Path, default):
    value = load_json_file(path, default)
    return value if isinstance(value, type(default)) else default


def _phase6k_save(path: Path, value) -> None:
    save_json_file(path, value)


def phase6k_append_event(service_id: str, event: str, actor: str, details: str = "") -> dict:
    item = {
        "id": uuid.uuid4().hex[:16],
        "service_id": service_id,
        "event": event,
        "actor": actor,
        "details": details[:2000],
        "created_at": datetime.now().isoformat(),
    }
    events = _phase6k_load(PHASE6K_EVENTS_FILE, [])
    events.append(item)
    _phase6k_save(PHASE6K_EVENTS_FILE, events[-10000:])
    structured_log(
        "phase6k.improvement_event",
        service_id=service_id,
        event=event,
        actor=actor,
    )
    return item


def phase6k_renewal_review(service_id: str) -> dict:
    service = phase6j_service_by_id(service_id)
    if not service:
        raise HTTPException(status_code=404, detail="Service record not found.")

    scorecards = [
        item for item in _phase6k_load(PHASE6K_SCORECARDS_FILE, [])
        if item.get("service_id") == service_id
    ]
    actions = [
        item for item in _phase6k_load(PHASE6K_ACTIONS_FILE, [])
        if item.get("service_id") == service_id
    ]
    signoffs = [
        item for item in _phase6k_load(PHASE6K_SIGNOFFS_FILE, [])
        if item.get("service_id") == service_id
    ]

    latest_scorecard = scorecards[-1] if scorecards else None
    open_critical_actions = [
        item for item in actions
        if item.get("priority") == "critical"
        and item.get("status", "open") not in {"completed", "cancelled"}
    ]

    active_signoffs = {}
    for item in signoffs:
        key = (item.get("approver", "").lower(), item.get("role", "").lower())
        if item.get("decision") == "approved":
            active_signoffs[key] = item
        elif item.get("decision") in {"rejected", "revoked"}:
            active_signoffs.pop(key, None)

    transition_reviews = _phase6j_load(PHASE6J_REVIEWS_FILE, [])
    latest_transition = next(
        (
            item for item in reversed(transition_reviews)
            if item.get("service_id") == service_id
        ),
        None,
    )

    blockers = []
    if not latest_transition or not latest_transition.get("transition_ready", False):
        blockers.append("Latest Phase 6J service transition review is not ready.")
    if not latest_scorecard:
        blockers.append("No service performance scorecard has been recorded.")
    else:
        if float(latest_scorecard.get("availability", 0)) < PHASE6K_MIN_AVAILABILITY:
            blockers.append("Service availability is below the renewal threshold.")
        if float(latest_scorecard.get("customer_score", 0)) < PHASE6K_MIN_CUSTOMER_SCORE:
            blockers.append("Customer score is below the renewal threshold.")
        if int(latest_scorecard.get("sla_breach_count", 0)) > 0:
            blockers.append("The latest scorecard contains SLA breaches.")

    if len(open_critical_actions) > PHASE6K_MAX_OPEN_CRITICAL_ACTIONS:
        blockers.append("Critical continuous-improvement actions remain open.")
    if len(active_signoffs) < PHASE6K_REQUIRED_RENEWAL_SIGNOFFS:
        blockers.append(
            f"{PHASE6K_REQUIRED_RENEWAL_SIGNOFFS} renewal-readiness signoffs are required."
        )

    recommendation = "renew"
    if not latest_scorecard:
        recommendation = "review_required"
    elif (
        float(latest_scorecard.get("availability", 0)) < PHASE6K_MIN_AVAILABILITY
        or float(latest_scorecard.get("customer_score", 0)) < PHASE6K_MIN_CUSTOMER_SCORE
    ):
        recommendation = "do_not_renew"
    elif blockers:
        recommendation = "conditional_renewal"

    review = {
        "id": uuid.uuid4().hex[:16],
        "service_id": service_id,
        "checked_at": datetime.now().isoformat(),
        "recommendation": recommendation,
        "renewal_ready": not blockers,
        "latest_scorecard": latest_scorecard,
        "open_critical_action_count": len(open_critical_actions),
        "active_signoff_count": len(active_signoffs),
        "required_signoff_count": PHASE6K_REQUIRED_RENEWAL_SIGNOFFS,
        "phase6j_transition_review_id": latest_transition.get("id") if latest_transition else None,
        "blockers": blockers,
        "automatic_billing_or_renewal_performed": False,
    }
    reviews = _phase6k_load(PHASE6K_RENEWALS_FILE, [])
    reviews.append(review)
    _phase6k_save(PHASE6K_RENEWALS_FILE, reviews[-5000:])
    structured_log(
        "phase6k.renewal_review",
        service_id=service_id,
        recommendation=recommendation,
        blocker_count=len(blockers),
    )
    return review


