@app.put("/api/service-performance/services/{service_id}/actions/{action_id}")
def phase6k_action_status(
    service_id: str,
    action_id: str,
    payload: Phase6KActionStatusModel,
    request: Request,
) -> dict:
    user = current_user(request)
    if not has_permission(user, "manage_settings"):
        raise HTTPException(status_code=403, detail="Settings permission is required.")

    records = _phase6k_load(PHASE6K_ACTIONS_FILE, [])
    item = next(
        (
            entry for entry in records
            if entry.get("id") == action_id and entry.get("service_id") == service_id
        ),
        None,
    )
    if not item:
        raise HTTPException(status_code=404, detail="Improvement action not found.")

    item["status"] = payload.status
    item["status_notes"] = payload.notes.strip()
    item["updated_at"] = datetime.now().isoformat()
    item["updated_by"] = user.get("id", "unknown")
    _phase6k_save(PHASE6K_ACTIONS_FILE, records)
    phase6k_append_event(
        service_id,
        f"improvement_action_{payload.status}",
        user.get("id", "unknown"),
        action_id,
    )
    return {"status": "complete", "action": item}


