# ============================================================================
# Phase 6L — Expansion Readiness, Compliance Evidence, and Portfolio Governance
# Local governance records only. No automatic sales, billing, deployment,
# customer communication, legal filing, or external provider action occurs.
# ============================================================================

PHASE6L_MARKER = "Phase 6L — Expansion Readiness, Compliance Evidence, and Portfolio Governance"
PHASE6L_PORTFOLIOS_FILE = RECORDINGS_FOLDER / "phase6l_portfolios.json"
PHASE6L_EVIDENCE_FILE = RECORDINGS_FOLDER / "phase6l_compliance_evidence.json"
PHASE6L_EXPANSIONS_FILE = RECORDINGS_FOLDER / "phase6l_expansion_requests.json"
PHASE6L_APPROVALS_FILE = RECORDINGS_FOLDER / "phase6l_expansion_approvals.json"
PHASE6L_REVIEWS_FILE = RECORDINGS_FOLDER / "phase6l_portfolio_reviews.json"

PHASE6L_REQUIRED_EVIDENCE_TYPES = {
    "security_review",
    "privacy_review",
    "service_performance",
    "support_readiness",
    "business_case",
}
PHASE6L_REQUIRED_APPROVALS = int(os.environ.get("PHASE6L_REQUIRED_APPROVALS", "2"))
PHASE6L_MIN_RENEWAL_SCORECARDS = int(os.environ.get("PHASE6L_MIN_RENEWAL_SCORECARDS", "1"))
PHASE6L_MAX_OPEN_CRITICAL_ACTIONS = int(os.environ.get("PHASE6L_MAX_OPEN_CRITICAL_ACTIONS", "0"))


class Phase6LPortfolioModel(BaseModel):
    name: str = Field(min_length=3, max_length=160)
    owner: str = Field(min_length=2, max_length=120)
    service_ids: list[str] = Field(min_length=1, max_length=500)
    market: str = Field(min_length=2, max_length=160)
    objective: str = Field(min_length=5, max_length=3000)
    notes: str = Field(default="", max_length=4000)


class Phase6LEvidenceModel(BaseModel):
    evidence_type: str = Field(min_length=2, max_length=120)
    title: str = Field(min_length=3, max_length=200)
    reference: str = Field(min_length=2, max_length=1000)
    verified: bool
    expires_at: str = Field(default="", max_length=40)
    notes: str = Field(default="", max_length=3000)


class Phase6LExpansionModel(BaseModel):
    target_scope: str = Field(min_length=3, max_length=1000)
    expected_customers: int = Field(ge=1, le=10000000)
    expected_monthly_value: float = Field(ge=0, le=1000000000)
    target_date: str = Field(min_length=8, max_length=40)
    capacity_plan: str = Field(min_length=5, max_length=4000)
    support_plan: str = Field(min_length=5, max_length=4000)
    rollback_plan: str = Field(min_length=5, max_length=4000)
    notes: str = Field(default="", max_length=4000)


class Phase6LApprovalModel(BaseModel):
    decision: str = Field(pattern="^(approved|rejected|revoked)$")
    approver: str = Field(min_length=2, max_length=120)
    role: str = Field(min_length=2, max_length=120)
    notes: str = Field(default="", max_length=3000)


def _phase6l_load(path: Path, default):
    value = load_json_file(path, default)
    return value if isinstance(value, type(default)) else default


def _phase6l_save(path: Path, value) -> None:
    save_json_file(path, value)


def phase6l_portfolio_by_id(portfolio_id: str) -> dict | None:
    return next(
        (
            item for item in _phase6l_load(PHASE6L_PORTFOLIOS_FILE, [])
            if item.get("id") == portfolio_id
        ),
        None,
    )


def phase6l_portfolio_review(portfolio_id: str) -> dict:
    portfolio = phase6l_portfolio_by_id(portfolio_id)
    if not portfolio:
        raise HTTPException(status_code=404, detail="Portfolio not found.")

    evidence = [
        item for item in _phase6l_load(PHASE6L_EVIDENCE_FILE, [])
        if item.get("portfolio_id") == portfolio_id
    ]
    expansions = [
        item for item in _phase6l_load(PHASE6L_EXPANSIONS_FILE, [])
        if item.get("portfolio_id") == portfolio_id
    ]
    approvals = [
        item for item in _phase6l_load(PHASE6L_APPROVALS_FILE, [])
        if item.get("portfolio_id") == portfolio_id
    ]

    latest_evidence = {}
    for item in evidence:
        latest_evidence[item.get("evidence_type")] = item

    verified_types = {
        key for key, item in latest_evidence.items() if item.get("verified") is True
    }
    missing_evidence = sorted(PHASE6L_REQUIRED_EVIDENCE_TYPES - verified_types)

    active_approvals = {}
    for item in approvals:
        key = (item.get("approver", "").lower(), item.get("role", "").lower())
        if item.get("decision") == "approved":
            active_approvals[key] = item
        elif item.get("decision") in {"rejected", "revoked"}:
            active_approvals.pop(key, None)

    latest_expansion = expansions[-1] if expansions else None
    blockers = []

    service_ids = portfolio.get("service_ids") or []
    missing_services = [
        service_id for service_id in service_ids
        if not phase6j_service_by_id(service_id)
    ]
    if missing_services:
        blockers.append(f"Unknown service IDs: {missing_services}.")

    renewal_reviews = _phase6k_load(PHASE6K_RENEWALS_FILE, [])
    for service_id in service_ids:
        service_reviews = [
            item for item in renewal_reviews if item.get("service_id") == service_id
        ]
        if len(service_reviews) < PHASE6L_MIN_RENEWAL_SCORECARDS:
            blockers.append(
                f"Service {service_id} does not have enough Phase 6K renewal reviews."
            )
        elif not service_reviews[-1].get("renewal_ready", False):
            blockers.append(f"Service {service_id} is not renewal-ready.")

    actions = _phase6k_load(PHASE6K_ACTIONS_FILE, [])
    open_critical = [
        item for item in actions
        if item.get("service_id") in service_ids
        and item.get("priority") == "critical"
        and item.get("status", "open") not in {"completed", "cancelled"}
    ]
    if len(open_critical) > PHASE6L_MAX_OPEN_CRITICAL_ACTIONS:
        blockers.append("Critical continuous-improvement actions remain open.")

    if missing_evidence:
        blockers.append(f"Required compliance evidence is missing: {missing_evidence}.")
    if not latest_expansion:
        blockers.append("No expansion request has been recorded.")
    if len(active_approvals) < PHASE6L_REQUIRED_APPROVALS:
        blockers.append(f"{PHASE6L_REQUIRED_APPROVALS} expansion approvals are required.")

    recommendation = "approve_expansion"
    if missing_evidence or missing_services:
        recommendation = "do_not_expand"
    elif blockers:
        recommendation = "conditional_expansion"

    review = {
        "id": uuid.uuid4().hex[:16],
        "portfolio_id": portfolio_id,
        "checked_at": datetime.now().isoformat(),
        "expansion_ready": not blockers,
        "recommendation": recommendation,
        "service_count": len(service_ids),
        "verified_evidence_types": sorted(verified_types),
        "missing_evidence_types": missing_evidence,
        "active_approval_count": len(active_approvals),
        "required_approval_count": PHASE6L_REQUIRED_APPROVALS,
        "latest_expansion_request_id": latest_expansion.get("id") if latest_expansion else None,
        "open_critical_action_count": len(open_critical),
        "blockers": blockers,
        "automatic_commercial_or_deployment_action_performed": False,
    }
    reviews = _phase6l_load(PHASE6L_REVIEWS_FILE, [])
    reviews.append(review)
    _phase6l_save(PHASE6L_REVIEWS_FILE, reviews[-5000:])
    structured_log(
        "phase6l.portfolio_review",
        portfolio_id=portfolio_id,
        expansion_ready=review["expansion_ready"],
        recommendation=recommendation,
        blocker_count=len(blockers),
    )
    return review


