# ============================================================================
# Phase 6M — Production Certification and Final Acceptance
# Local certification records only. No automatic deployment, production
# release, legal attestation, billing, or customer communication occurs.
# ============================================================================

PHASE6M_MARKER = "Phase 6M — Production Certification and Final Acceptance"
PHASE6M_CERTIFICATIONS_FILE = RECORDINGS_FOLDER / "phase6m_certifications.json"
PHASE6M_ACCEPTANCE_FILE = RECORDINGS_FOLDER / "phase6m_final_acceptance.json"
PHASE6M_EVIDENCE_FILE = RECORDINGS_FOLDER / "phase6m_certification_evidence.json"
PHASE6M_APPROVALS_FILE = RECORDINGS_FOLDER / "phase6m_acceptance_approvals.json"
PHASE6M_REVIEWS_FILE = RECORDINGS_FOLDER / "phase6m_release_reviews.json"

PHASE6M_REQUIRED_DOMAINS = {
    "security",
    "privacy",
    "reliability",
    "operations",
    "support",
    "business",
}
PHASE6M_REQUIRED_APPROVALS = int(os.environ.get("PHASE6M_REQUIRED_APPROVALS", "3"))
PHASE6M_REQUIRED_TEST_PASS_RATE = float(os.environ.get("PHASE6M_REQUIRED_TEST_PASS_RATE", "100.0"))
PHASE6M_MAX_OPEN_CRITICAL_FINDINGS = int(os.environ.get("PHASE6M_MAX_OPEN_CRITICAL_FINDINGS", "0"))


class Phase6MCertificationModel(BaseModel):
    release_name: str = Field(min_length=3, max_length=160)
    version: str = Field(min_length=1, max_length=60)
    owner: str = Field(min_length=2, max_length=120)
    portfolio_id: str = Field(min_length=2, max_length=120)
    test_pass_rate: float = Field(ge=0, le=100)
    open_critical_findings: int = Field(ge=0, le=100000)
    release_notes: str = Field(min_length=5, max_length=5000)


class Phase6MEvidenceModel(BaseModel):
    domain: str = Field(min_length=2, max_length=120)
    title: str = Field(min_length=3, max_length=200)
    reference: str = Field(min_length=2, max_length=1000)
    verified: bool
    verifier: str = Field(min_length=2, max_length=120)
    notes: str = Field(default="", max_length=3000)


class Phase6MApprovalModel(BaseModel):
    decision: str = Field(pattern="^(approved|rejected|revoked)$")
    approver: str = Field(min_length=2, max_length=120)
    role: str = Field(min_length=2, max_length=120)
    notes: str = Field(default="", max_length=3000)


class Phase6MAcceptanceModel(BaseModel):
    decision: str = Field(pattern="^(accepted|rejected|conditional)$")
    accepted_by: str = Field(min_length=2, max_length=120)
    role: str = Field(min_length=2, max_length=120)
    conditions: list[str] = Field(default_factory=list, max_length=50)
    notes: str = Field(default="", max_length=4000)


def _phase6m_load(path: Path, default):
    value = load_json_file(path, default)
    return value if isinstance(value, type(default)) else default


def _phase6m_save(path: Path, value) -> None:
    save_json_file(path, value)


def phase6m_certification_by_id(certification_id: str) -> dict | None:
    return next(
        (
            item for item in _phase6m_load(PHASE6M_CERTIFICATIONS_FILE, [])
            if item.get("id") == certification_id
        ),
        None,
    )


def phase6m_release_review(certification_id: str) -> dict:
    certification = phase6m_certification_by_id(certification_id)
    if not certification:
        raise HTTPException(status_code=404, detail="Certification record not found.")

    portfolio_id = certification.get("portfolio_id")
    portfolio_reviews = _phase6l_load(PHASE6L_REVIEWS_FILE, [])
    latest_portfolio_review = next(
        (
            item for item in reversed(portfolio_reviews)
            if item.get("portfolio_id") == portfolio_id
        ),
        None,
    )

    evidence = [
        item for item in _phase6m_load(PHASE6M_EVIDENCE_FILE, [])
        if item.get("certification_id") == certification_id
    ]
    approvals = [
        item for item in _phase6m_load(PHASE6M_APPROVALS_FILE, [])
        if item.get("certification_id") == certification_id
    ]
    acceptance = [
        item for item in _phase6m_load(PHASE6M_ACCEPTANCE_FILE, [])
        if item.get("certification_id") == certification_id
    ]

    latest_evidence = {}
    for item in evidence:
        latest_evidence[item.get("domain")] = item

    verified_domains = {
        key for key, item in latest_evidence.items() if item.get("verified") is True
    }
    missing_domains = sorted(PHASE6M_REQUIRED_DOMAINS - verified_domains)

    active_approvals = {}
    for item in approvals:
        key = (item.get("approver", "").lower(), item.get("role", "").lower())
        if item.get("decision") == "approved":
            active_approvals[key] = item
        elif item.get("decision") in {"rejected", "revoked"}:
            active_approvals.pop(key, None)

    latest_acceptance = acceptance[-1] if acceptance else None

    blockers = []
    if not latest_portfolio_review or not latest_portfolio_review.get("expansion_ready", False):
        blockers.append("Latest Phase 6L portfolio review is not expansion-ready.")
    if float(certification.get("test_pass_rate", 0)) < PHASE6M_REQUIRED_TEST_PASS_RATE:
        blockers.append("Certification test pass rate is below the required threshold.")
    if int(certification.get("open_critical_findings", 0)) > PHASE6M_MAX_OPEN_CRITICAL_FINDINGS:
        blockers.append("Open critical findings exceed the allowed limit.")
    if missing_domains:
        blockers.append(f"Certification evidence is missing for: {missing_domains}.")
    if len(active_approvals) < PHASE6M_REQUIRED_APPROVALS:
        blockers.append(f"{PHASE6M_REQUIRED_APPROVALS} final approvals are required.")
    if not latest_acceptance:
        blockers.append("Final acceptance has not been recorded.")
    elif latest_acceptance.get("decision") == "rejected":
        blockers.append("Final acceptance was rejected.")
    elif latest_acceptance.get("decision") == "conditional":
        blockers.append("Final acceptance remains conditional.")

    recommendation = "certified"
    if missing_domains or certification.get("open_critical_findings", 0):
        recommendation = "not_certified"
    elif blockers:
        recommendation = "conditional_certification"

    review = {
        "id": uuid.uuid4().hex[:16],
        "certification_id": certification_id,
        "checked_at": datetime.now().isoformat(),
        "production_certified": not blockers,
        "recommendation": recommendation,
        "verified_domains": sorted(verified_domains),
        "missing_domains": missing_domains,
        "active_approval_count": len(active_approvals),
        "required_approval_count": PHASE6M_REQUIRED_APPROVALS,
        "latest_acceptance_decision": latest_acceptance.get("decision") if latest_acceptance else None,
        "phase6l_review_id": latest_portfolio_review.get("id") if latest_portfolio_review else None,
        "blockers": blockers,
        "automatic_release_or_deployment_performed": False,
    }
    reviews = _phase6m_load(PHASE6M_REVIEWS_FILE, [])
    reviews.append(review)
    _phase6m_save(PHASE6M_REVIEWS_FILE, reviews[-5000:])
    structured_log(
        "phase6m.release_review",
        certification_id=certification_id,
        production_certified=review["production_certified"],
        recommendation=recommendation,
        blocker_count=len(blockers),
    )
    return review


