# ============================================================================
# Phase 6N — Long-Term Operations, Audit, and Maintenance
# Final Phase 6 governance layer. Local records only. No automatic patching,
# deployment, customer communication, billing, legal filing, or provider action.
# ============================================================================

PHASE6N_MARKER = "Phase 6N — Long-Term Operations, Audit, and Maintenance"
PHASE6N_MAINTENANCE_FILE = RECORDINGS_FOLDER / "phase6n_maintenance_register.json"
PHASE6N_AUDITS_FILE = RECORDINGS_FOLDER / "phase6n_audit_register.json"
PHASE6N_RISKS_FILE = RECORDINGS_FOLDER / "phase6n_operational_risks.json"
PHASE6N_REVIEWS_FILE = RECORDINGS_FOLDER / "phase6n_lifecycle_reviews.json"
PHASE6N_SIGNOFFS_FILE = RECORDINGS_FOLDER / "phase6n_lifecycle_signoffs.json"

PHASE6N_REQUIRED_AUDIT_TYPES = {
    "security",
    "privacy",
    "availability",
    "backup_restore",
    "access_control",
    "incident_response",
}
PHASE6N_REQUIRED_SIGNOFFS = int(os.environ.get("PHASE6N_REQUIRED_SIGNOFFS", "2"))
PHASE6N_MAX_OPEN_CRITICAL_RISKS = int(os.environ.get("PHASE6N_MAX_OPEN_CRITICAL_RISKS", "0"))
PHASE6N_MAX_OVERDUE_MAINTENANCE = int(os.environ.get("PHASE6N_MAX_OVERDUE_MAINTENANCE", "0"))


class Phase6NMaintenanceModel(BaseModel):
    title: str = Field(min_length=3, max_length=200)
    owner: str = Field(min_length=2, max_length=120)
    category: str = Field(min_length=2, max_length=120)
    cadence: str = Field(min_length=2, max_length=120)
    due_date: str = Field(min_length=8, max_length=40)
    procedure: str = Field(min_length=5, max_length=4000)
    rollback_plan: str = Field(min_length=5, max_length=4000)
    notes: str = Field(default="", max_length=3000)


class Phase6NMaintenanceStatusModel(BaseModel):
    status: str = Field(pattern="^(scheduled|in_progress|completed|overdue|cancelled)$")
    notes: str = Field(default="", max_length=3000)


class Phase6NAuditModel(BaseModel):
    audit_type: str = Field(min_length=2, max_length=120)
    auditor: str = Field(min_length=2, max_length=120)
    result: str = Field(pattern="^(passed|failed|partial)$")
    evidence_reference: str = Field(min_length=2, max_length=1000)
    findings: list[str] = Field(default_factory=list, max_length=100)
    notes: str = Field(default="", max_length=4000)


class Phase6NRiskModel(BaseModel):
    title: str = Field(min_length=3, max_length=200)
    severity: str = Field(pattern="^(low|medium|high|critical)$")
    owner: str = Field(min_length=2, max_length=120)
    mitigation: str = Field(min_length=5, max_length=4000)
    target_date: str = Field(min_length=8, max_length=40)
    notes: str = Field(default="", max_length=3000)


class Phase6NRiskStatusModel(BaseModel):
    status: str = Field(pattern="^(open|mitigating|accepted|resolved|closed)$")
    notes: str = Field(default="", max_length=3000)


class Phase6NSignoffModel(BaseModel):
    decision: str = Field(pattern="^(approved|rejected|revoked)$")
    approver: str = Field(min_length=2, max_length=120)
    role: str = Field(min_length=2, max_length=120)
    notes: str = Field(default="", max_length=3000)


def _phase6n_load(path: Path, default):
    value = load_json_file(path, default)
    return value if isinstance(value, type(default)) else default


def _phase6n_save(path: Path, value) -> None:
    save_json_file(path, value)


def phase6n_lifecycle_review(certification_id: str) -> dict:
    certification = phase6m_certification_by_id(certification_id)
    if not certification:
        raise HTTPException(status_code=404, detail="Certification record not found.")

    certification_reviews = _phase6m_load(PHASE6M_REVIEWS_FILE, [])
    latest_certification = next(
        (
            item for item in reversed(certification_reviews)
            if item.get("certification_id") == certification_id
        ),
        None,
    )

    maintenance = _phase6n_load(PHASE6N_MAINTENANCE_FILE, [])
    audits = _phase6n_load(PHASE6N_AUDITS_FILE, [])
    risks = _phase6n_load(PHASE6N_RISKS_FILE, [])
    signoffs = _phase6n_load(PHASE6N_SIGNOFFS_FILE, [])

    latest_audits = {}
    for item in audits:
        if item.get("certification_id") == certification_id:
            latest_audits[item.get("audit_type")] = item

    passed_audit_types = {
        key for key, item in latest_audits.items() if item.get("result") == "passed"
    }
    missing_audits = sorted(PHASE6N_REQUIRED_AUDIT_TYPES - passed_audit_types)

    relevant_maintenance = [
        item for item in maintenance
        if item.get("certification_id") == certification_id
    ]
    overdue_maintenance = [
        item for item in relevant_maintenance
        if item.get("status") == "overdue"
    ]

    relevant_risks = [
        item for item in risks
        if item.get("certification_id") == certification_id
    ]
    open_critical_risks = [
        item for item in relevant_risks
        if item.get("severity") == "critical"
        and item.get("status", "open") not in {"resolved", "closed", "accepted"}
    ]

    active_signoffs = {}
    for item in signoffs:
        if item.get("certification_id") != certification_id:
            continue
        key = (item.get("approver", "").lower(), item.get("role", "").lower())
        if item.get("decision") == "approved":
            active_signoffs[key] = item
        elif item.get("decision") in {"rejected", "revoked"}:
            active_signoffs.pop(key, None)

    blockers = []
    if not latest_certification or not latest_certification.get("production_certified", False):
        blockers.append("Latest Phase 6M certification is not production-certified.")
    if missing_audits:
        blockers.append(f"Required lifecycle audits are missing or not passed: {missing_audits}.")
    if len(overdue_maintenance) > PHASE6N_MAX_OVERDUE_MAINTENANCE:
        blockers.append("Overdue maintenance exceeds the allowed limit.")
    if len(open_critical_risks) > PHASE6N_MAX_OPEN_CRITICAL_RISKS:
        blockers.append("Open critical operational risks exceed the allowed limit.")
    if len(active_signoffs) < PHASE6N_REQUIRED_SIGNOFFS:
        blockers.append(f"{PHASE6N_REQUIRED_SIGNOFFS} lifecycle signoffs are required.")

    status = "stable_operations"
    if open_critical_risks or missing_audits:
        status = "remediation_required"
    elif blockers:
        status = "conditional_operations"

    review = {
        "id": uuid.uuid4().hex[:16],
        "certification_id": certification_id,
        "checked_at": datetime.now().isoformat(),
        "lifecycle_ready": not blockers,
        "status": status,
        "passed_audit_types": sorted(passed_audit_types),
        "missing_audit_types": missing_audits,
        "maintenance_count": len(relevant_maintenance),
        "overdue_maintenance_count": len(overdue_maintenance),
        "open_critical_risk_count": len(open_critical_risks),
        "active_signoff_count": len(active_signoffs),
        "required_signoff_count": PHASE6N_REQUIRED_SIGNOFFS,
        "phase6m_review_id": latest_certification.get("id") if latest_certification else None,
        "blockers": blockers,
        "automatic_patch_or_deployment_performed": False,
        "phase6_complete": not blockers,
    }
    reviews = _phase6n_load(PHASE6N_REVIEWS_FILE, [])
    reviews.append(review)
    _phase6n_save(PHASE6N_REVIEWS_FILE, reviews[-5000:])
    structured_log(
        "phase6n.lifecycle_review",
        certification_id=certification_id,
        lifecycle_ready=review["lifecycle_ready"],
        status=status,
        blocker_count=len(blockers),
    )
    return review


