# ============================================================================
# AnyAiCam VMS v1.0.0 — Production Release Baseline
# Formal version metadata, compatibility validation, release manifest,
# feature-flag registry, and non-destructive release health reporting.
# ============================================================================

ANYAICAM_VERSION_MARKER = "AnyAiCam VMS v1.0.0 — Production Release Baseline"
ANYAICAM_VERSION = "1.0.0"
ANYAICAM_RELEASE_CHANNEL = os.environ.get("ANYAICAM_RELEASE_CHANNEL", "stable")
ANYAICAM_SCHEMA_VERSION = 1
ANYAICAM_RELEASED_AT = "2026-08-05"

V1_RELEASE_MANIFEST_FILE = RECORDINGS_FOLDER / "v1_release_manifest.json"
V1_FEATURE_FLAGS_FILE = RECORDINGS_FOLDER / "v1_feature_flags.json"
V1_COMPATIBILITY_FILE = RECORDINGS_FOLDER / "v1_compatibility_checks.json"

V1_DEFAULT_FEATURE_FLAGS = {
    "phase6e_operations": True,
    "phase6f_pilots": True,
    "phase6g_outcome_review": True,
    "phase6h_rollout_governance": True,
    "phase6i_assurance": True,
    "phase6j_service_transition": True,
    "phase6k_performance": True,
    "phase6l_portfolio_governance": True,
    "phase6m_certification": True,
    "phase6n_lifecycle": True,
}


class V1FeatureFlagModel(BaseModel):
    flag: str = Field(min_length=2, max_length=120)
    enabled: bool
    reason: str = Field(default="", max_length=2000)


def _v1_load(path: Path, default):
    value = load_json_file(path, default)
    return value if isinstance(value, type(default)) else default


def _v1_save(path: Path, value) -> None:
    save_json_file(path, value)


def v1_feature_flags() -> dict:
    saved = _v1_load(V1_FEATURE_FLAGS_FILE, {})
    merged = dict(V1_DEFAULT_FEATURE_FLAGS)
    merged.update({
        str(key): bool(value)
        for key, value in saved.items()
        if isinstance(key, str)
    })
    return merged


def v1_compatibility_check() -> dict:
    checks = {
        "python_runtime_available": True,
        "recordings_folder_exists": RECORDINGS_FOLDER.exists(),
        "recordings_folder_writable": os.access(RECORDINGS_FOLDER, os.W_OK),
        "backups_folder_exists": BACKUPS_FOLDER.exists(),
        "phase6n_present": "phase6n_lifecycle_review" in globals(),
        "page_shell_present": callable(globals().get("page_shell")),
        "permission_system_present": callable(globals().get("has_permission")),
        "json_persistence_present": (
            callable(globals().get("load_json_file"))
            and callable(globals().get("save_json_file"))
        ),
    }
    compatible = all(checks.values())
    result = {
        "id": uuid.uuid4().hex[:16],
        "version": ANYAICAM_VERSION,
        "schema_version": ANYAICAM_SCHEMA_VERSION,
        "release_channel": ANYAICAM_RELEASE_CHANNEL,
        "checked_at": datetime.now().isoformat(),
        "compatible": compatible,
        "checks": checks,
        "automatic_migration_performed": False,
        "automatic_deployment_performed": False,
    }
    records = _v1_load(V1_COMPATIBILITY_FILE, [])
    records.append(result)
    _v1_save(V1_COMPATIBILITY_FILE, records[-2000:])
    structured_log(
        "v1.compatibility_check",
        version=ANYAICAM_VERSION,
        compatible=compatible,
    )
    return result


def v1_release_manifest() -> dict:
    flags = v1_feature_flags()
    compatibility = v1_compatibility_check()
    manifest = {
        "product": "AnyAiCam VMS",
        "version": ANYAICAM_VERSION,
        "release_channel": ANYAICAM_RELEASE_CHANNEL,
        "schema_version": ANYAICAM_SCHEMA_VERSION,
        "released_at": ANYAICAM_RELEASED_AT,
        "phase6_complete": True,
        "compatibility": compatibility,
        "feature_flags": flags,
        "enabled_feature_count": sum(flags.values()),
        "total_feature_count": len(flags),
        "release_status": "ready" if compatibility["compatible"] else "blocked",
        "automatic_release_performed": False,
    }
    _v1_save(V1_RELEASE_MANIFEST_FILE, manifest)
    return manifest


