# ============================================================================
# AnyAiCam VMS v1.0.1 — Cloud ID Management
# Site-level cloud identifiers only. No provider API calls or secret storage.
# ============================================================================

ANYAICAM_V101_MARKER = "AnyAiCam VMS v1.0.1 — Cloud ID Management"
ANYAICAM_VERSION = "1.0.1"
V101_CLOUD_SITES_FILE = RECORDINGS_FOLDER / "v101_cloud_sites.json"
V101_CLOUD_AUDIT_FILE = RECORDINGS_FOLDER / "v101_cloud_id_audit.json"
V101_ALLOWED_PROVIDERS = {"videoloft", "other"}

class V101CloudIdUpdateModel(BaseModel):
    cloud_id: str = Field(min_length=2, max_length=200)
    cloud_provider: str = Field(default="videoloft", min_length=2, max_length=80)

class V101CloudStatusModel(BaseModel):
    cloud_status: str = Field(pattern="^(not_connected|connected|suspended|error)$")
    notes: str = Field(default="", max_length=2000)

def _v101_load(path: Path, default):
    value = load_json_file(path, default)
    return value if isinstance(value, type(default)) else default

def _v101_save(path: Path, value) -> None:
    save_json_file(path, value)

def v101_clean_cloud_id(value: str | None) -> str | None:
    if value is None:
        return None
    cleaned = value.strip()
    if not cleaned:
        return None
    allowed = set("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-_:.@")
    if any(character not in allowed for character in cleaned):
        raise HTTPException(status_code=400, detail="Cloud ID contains unsupported characters.")
    return cleaned

def v101_cloud_site_by_id(site_id: str) -> dict | None:
    return next((item for item in _v101_load(V101_CLOUD_SITES_FILE, []) if item.get("site_id") == site_id), None)

def v101_record_cloud_audit(site_id: str, action: str, actor: str, provider: str = "", notes: str = "") -> dict:
    item = {
        "id": uuid.uuid4().hex[:16], "site_id": site_id, "action": action,
        "actor": actor, "provider": provider, "notes": notes[:2000],
        "created_at": datetime.now().isoformat(),
    }
    records = _v101_load(V101_CLOUD_AUDIT_FILE, [])
    records.append(item)
    _v101_save(V101_CLOUD_AUDIT_FILE, records[-10000:])
    structured_log("v101.cloud_id_audit", site_id=site_id, action=action, actor=actor, provider=provider)
    return item

@app.get("/api/cloud-sites")
def v101_list_cloud_sites(request: Request) -> dict:
    user = current_user(request)
    if not has_permission(user, "manage_settings"):
        raise HTTPException(status_code=403, detail="Settings permission is required.")
    return {"sites": list(reversed(_v101_load(V101_CLOUD_SITES_FILE, [])[-2000:]))}

@app.get("/api/cloud-sites/{site_id}")
def v101_get_cloud_site(site_id: str, request: Request) -> dict:
    user = current_user(request)
    if not has_permission(user, "manage_settings"):
        raise HTTPException(status_code=403, detail="Settings permission is required.")
    site = v101_cloud_site_by_id(site_id)
    if not site:
        raise HTTPException(status_code=404, detail="Cloud site not found.")
    return {"site": site}

@app.put("/api/cloud-sites/{site_id}/cloud-id")
def v101_update_cloud_id(site_id: str, payload: V101CloudIdUpdateModel, request: Request) -> dict:
    user = current_user(request)
    if not has_permission(user, "manage_settings"):
        raise HTTPException(status_code=403, detail="Settings permission is required.")
    provider = payload.cloud_provider.strip().lower()
    if provider not in V101_ALLOWED_PROVIDERS:
        raise HTTPException(status_code=400, detail="Unsupported cloud provider.")
    cloud_id = v101_clean_cloud_id(payload.cloud_id)
    records = _v101_load(V101_CLOUD_SITES_FILE, [])
    site = next((item for item in records if item.get("site_id") == site_id), None)
    now = datetime.now().isoformat()
    if site is None:
        site = {"site_id": site_id, "created_at": now, "created_by": user.get("id", "unknown")}
        records.append(site)
    site.update({
        "cloud_provider": provider, "cloud_id": cloud_id,
        "cloud_status": "connected" if cloud_id else "not_connected",
        "cloud_id_updated_at": now, "cloud_id_updated_by": user.get("id", "unknown"),
        "updated_at": now,
    })
    _v101_save(V101_CLOUD_SITES_FILE, records)
    v101_record_cloud_audit(site_id, "cloud_id_updated", user.get("id", "unknown"), provider)
    return {"status": "complete", "message": "Cloud ID saved.", "site": site,
            "external_activation_performed": False, "credential_or_secret_stored": False}

@app.delete("/api/cloud-sites/{site_id}/cloud-id")
def v101_remove_cloud_id(site_id: str, request: Request) -> dict:
    user = current_user(request)
    if not has_permission(user, "manage_settings"):
        raise HTTPException(status_code=403, detail="Settings permission is required.")
    records = _v101_load(V101_CLOUD_SITES_FILE, [])
    site = next((item for item in records if item.get("site_id") == site_id), None)
    if not site:
        raise HTTPException(status_code=404, detail="Cloud site not found.")
    provider = site.get("cloud_provider", "")
    site["cloud_id"] = None
    site["cloud_status"] = "not_connected"
    site["cloud_id_updated_at"] = datetime.now().isoformat()
    site["cloud_id_updated_by"] = user.get("id", "unknown")
    _v101_save(V101_CLOUD_SITES_FILE, records)
    v101_record_cloud_audit(site_id, "cloud_id_removed", user.get("id", "unknown"), provider)
    return {"status": "complete", "message": "Cloud ID removed.", "external_deactivation_performed": False}

@app.put("/api/cloud-sites/{site_id}/status")
def v101_update_cloud_status(site_id: str, payload: V101CloudStatusModel, request: Request) -> dict:
    user = current_user(request)
    if not has_permission(user, "manage_settings"):
        raise HTTPException(status_code=403, detail="Settings permission is required.")
    records = _v101_load(V101_CLOUD_SITES_FILE, [])
    site = next((item for item in records if item.get("site_id") == site_id), None)
    if not site:
        raise HTTPException(status_code=404, detail="Cloud site not found.")
    site["cloud_status"] = payload.cloud_status
    site["status_notes"] = payload.notes.strip()
    site["updated_at"] = datetime.now().isoformat()
    site["updated_by"] = user.get("id", "unknown")
    _v101_save(V101_CLOUD_SITES_FILE, records)
    v101_record_cloud_audit(site_id, f"status_{payload.cloud_status}", user.get("id", "unknown"),
                            site.get("cloud_provider", ""), payload.notes)
    return {"status": "complete", "site": site, "external_action_performed": False}

@app.get("/api/cloud-sites/{site_id}/audit")
def v101_cloud_audit(site_id: str, request: Request) -> dict:
    user = current_user(request)
    if not has_permission(user, "manage_settings"):
        raise HTTPException(status_code=403, detail="Settings permission is required.")
    records = [item for item in _v101_load(V101_CLOUD_AUDIT_FILE, []) if item.get("site_id") == site_id]
    return {"audit": list(reversed(records[-500:]))}

