# ============================================================================
# AnyAiCam VMS v1.1.0 — Camera Discovery and Secure Credential Session
# Bounded, opt-in local discovery. Credentials are held in memory only and are
# never written to JSON, logs, backups, or audit records.
# ============================================================================

ANYAICAM_V110_MARKER = "AnyAiCam VMS v1.1.0 — Camera Discovery and Secure Credential Session"
ANYAICAM_VERSION = "1.1.0"

V110_DISCOVERY_FILE = RECORDINGS_FOLDER / "v110_camera_discovery.json"
V110_MAX_HOSTS = int(os.environ.get("V110_MAX_HOSTS", "256"))
V110_CONNECT_TIMEOUT = float(os.environ.get("V110_CONNECT_TIMEOUT", "0.35"))
V110_ALLOWED_PORTS = tuple(
    int(value.strip())
    for value in os.environ.get("V110_ALLOWED_PORTS", "80,443,554,8000,8080,8443").split(",")
    if value.strip().isdigit()
)

# Process-memory credential sessions only. They disappear when the app restarts.
V110_CREDENTIAL_SESSIONS: dict[str, dict] = {}


class V110DiscoveryModel(BaseModel):
    network: str = Field(min_length=3, max_length=64)
    ports: list[int] = Field(default_factory=lambda: list(V110_ALLOWED_PORTS), max_length=20)
    site_id: str = Field(min_length=1, max_length=160)
    consent_confirmed: bool


class V110CredentialSessionModel(BaseModel):
    username: str = Field(min_length=1, max_length=160)
    password: str = Field(min_length=1, max_length=512)
    device_ip: str = Field(min_length=3, max_length=64)
    site_id: str = Field(min_length=1, max_length=160)


def _v110_load(path: Path, default):
    value = load_json_file(path, default)
    return value if isinstance(value, type(default)) else default


def _v110_save(path: Path, value) -> None:
    save_json_file(path, value)


def v110_validate_network(network: str):
    import ipaddress
    try:
        parsed = ipaddress.ip_network(network.strip(), strict=False)
    except ValueError as exc:
        raise HTTPException(status_code=400, detail="Invalid network range.") from exc

    if not parsed.is_private:
        raise HTTPException(
            status_code=400,
            detail="Only private local-network ranges are allowed.",
        )
    if parsed.num_addresses > V110_MAX_HOSTS:
        raise HTTPException(
            status_code=400,
            detail=f"Discovery is limited to {V110_MAX_HOSTS} addresses.",
        )
    return parsed


def v110_probe_host(host: str, ports: list[int]) -> dict | None:
    import socket
    open_ports = []
    for port in ports:
        if port not in V110_ALLOWED_PORTS:
            continue
        try:
            with socket.create_connection((host, port), timeout=V110_CONNECT_TIMEOUT):
                open_ports.append(port)
        except OSError:
            continue
    if not open_ports:
        return None

    hints = []
    if 554 in open_ports:
        hints.append("rtsp")
    if any(port in open_ports for port in (80, 443, 8000, 8080, 8443)):
        hints.append("web")
    return {
        "ip": host,
        "open_ports": open_ports,
        "service_hints": hints,
        "classification": "possible_camera_or_recorder",
        "credential_status": "not_provided",
    }


@app.post("/api/camera-discovery/scan")
def v110_scan(payload: V110DiscoveryModel, request: Request) -> dict:
    user = current_user(request)
    if not has_permission(user, "manage_settings"):
        raise HTTPException(status_code=403, detail="Settings permission is required.")
    if not payload.consent_confirmed:
        raise HTTPException(
            status_code=400,
            detail="Local-network scan consent must be confirmed.",
        )

    network = v110_validate_network(payload.network)
    ports = sorted({
        int(port) for port in payload.ports
        if int(port) in V110_ALLOWED_PORTS
    })
    if not ports:
        raise HTTPException(status_code=400, detail="No allowed discovery ports selected.")

    devices = []
    for host in network.hosts():
        result = v110_probe_host(str(host), ports)
        if result:
            devices.append(result)

    record = {
        "id": uuid.uuid4().hex[:16],
        "site_id": payload.site_id.strip(),
        "network": str(network),
        "ports": ports,
        "device_count": len(devices),
        "devices": devices,
        "scanned_at": datetime.now().isoformat(),
        "scanned_by": user.get("id", "unknown"),
        "credential_data_stored": False,
        "authentication_attempted": False,
    }
    records = _v110_load(V110_DISCOVERY_FILE, [])
    records.append(record)
    _v110_save(V110_DISCOVERY_FILE, records[-500:])
    structured_log(
        "v110.camera_discovery",
        site_id=record["site_id"],
        network=record["network"],
        device_count=len(devices),
        actor=user.get("id", "unknown"),
    )
    return record


@app.post("/api/camera-discovery/credential-session")
def v110_create_credential_session(
    payload: V110CredentialSessionModel,
    request: Request,
) -> dict:
    user = current_user(request)
    if not has_permission(user, "manage_settings"):
        raise HTTPException(status_code=403, detail="Settings permission is required.")

    import ipaddress
    try:
        ip = ipaddress.ip_address(payload.device_ip.strip())
    except ValueError as exc:
        raise HTTPException(status_code=400, detail="Invalid device IP address.") from exc
    if not ip.is_private:
        raise HTTPException(status_code=400, detail="Only private device addresses are allowed.")

    token = uuid.uuid4().hex
    V110_CREDENTIAL_SESSIONS[token] = {
        "site_id": payload.site_id.strip(),
        "device_ip": str(ip),
        "username": payload.username,
        "password": payload.password,
        "created_at": datetime.now().isoformat(),
        "created_by": user.get("id", "unknown"),
    }

    structured_log(
        "v110.credential_session_created",
        site_id=payload.site_id.strip(),
        device_ip=str(ip),
        actor=user.get("id", "unknown"),
        username_present=bool(payload.username),
        password_present=bool(payload.password),
    )
    return {
        "status": "complete",
        "session_token": token,
        "device_ip": str(ip),
        "credentials_persisted": False,
        "authentication_attempted": False,
        "message": "Credential session created in memory only.",
    }


@app.delete("/api/camera-discovery/credential-session/{session_token}")
def v110_delete_credential_session(session_token: str, request: Request) -> dict:
    user = current_user(request)
    if not has_permission(user, "manage_settings"):
        raise HTTPException(status_code=403, detail="Settings permission is required.")

    session = V110_CREDENTIAL_SESSIONS.pop(session_token, None)
    if not session:
        raise HTTPException(status_code=404, detail="Credential session not found.")

    return {
        "status": "complete",
        "message": "Credential session removed from memory.",
        "credentials_persisted": False,
    }


@app.get("/api/camera-discovery/history")
def v110_discovery_history(request: Request) -> dict:
    user = current_user(request)
    if not has_permission(user, "manage_settings"):
        raise HTTPException(status_code=403, detail="Settings permission is required.")
    records = _v110_load(V110_DISCOVERY_FILE, [])
    return {"history": list(reversed(records[-100:]))}


