# ============================================================================
# AnyAiCam VMS v1.1.1 — Camera Verification and Explicit Authentication
# One selected device, one explicit verification attempt, sanitized persistence.
# Credentials remain in the v1.1.0 in-memory session and are never written.
# ============================================================================

ANYAICAM_V111_MARKER = "AnyAiCam VMS v1.1.1 — Camera Verification and Explicit Authentication"
ANYAICAM_VERSION = "1.1.1"

V111_VERIFICATION_FILE = RECORDINGS_FOLDER / "v111_camera_verifications.json"
V111_RATE_LIMIT_SECONDS = int(os.environ.get("V111_RATE_LIMIT_SECONDS", "15"))
V111_HTTP_PATHS = ("/", "/doc/page/login.asp", "/ISAPI/System/deviceInfo")
V111_LAST_ATTEMPT: dict[str, float] = {}


class V111VerifyModel(BaseModel):
    session_token: str = Field(min_length=16, max_length=128)
    selected_device_ip: str = Field(min_length=3, max_length=64)
    site_id: str = Field(min_length=1, max_length=160)
    consent_confirmed: bool
    test_http: bool = True
    test_rtsp: bool = True
    test_onvif: bool = True


def _v111_load(path: Path, default):
    value = load_json_file(path, default)
    return value if isinstance(value, type(default)) else default


def _v111_save(path: Path, value) -> None:
    save_json_file(path, value)


def v111_check_rate_limit(device_ip: str) -> None:
    import time
    now = time.monotonic()
    previous = V111_LAST_ATTEMPT.get(device_ip)
    if previous is not None and now - previous < V111_RATE_LIMIT_SECONDS:
        wait_seconds = max(1, int(V111_RATE_LIMIT_SECONDS - (now - previous)))
        raise HTTPException(
            status_code=429,
            detail=f"Wait {wait_seconds} seconds before another verification attempt.",
        )
    V111_LAST_ATTEMPT[device_ip] = now


def v111_http_verify(device_ip: str, username: str, password: str) -> dict:
    import base64
    import ssl
    import urllib.error
    import urllib.request

    credentials = base64.b64encode(
        f"{username}:{password}".encode("utf-8")
    ).decode("ascii")
    headers = {
        "Authorization": f"Basic {credentials}",
        "User-Agent": "AnyAiCam-VMS/1.1.1",
        "Accept": "application/xml,text/xml,text/html,*/*",
    }
    context = ssl._create_unverified_context()
    attempts = []

    for scheme, port in (("http", 80), ("https", 443)):
        for path in V111_HTTP_PATHS:
            url = f"{scheme}://{device_ip}:{port}{path}"
            request = urllib.request.Request(url, headers=headers, method="GET")
            try:
                with urllib.request.urlopen(
                    request,
                    timeout=3,
                    context=context if scheme == "https" else None,
                ) as response:
                    body = response.read(4096)
                    attempts.append({
                        "scheme": scheme,
                        "port": port,
                        "path": path,
                        "status": response.status,
                        "authenticated": 200 <= response.status < 400,
                        "content_type": response.headers.get("content-type", ""),
                        "body_sample_length": len(body),
                    })
                    if 200 <= response.status < 400:
                        return {
                            "supported": True,
                            "authenticated": True,
                            "attempts": attempts,
                        }
            except urllib.error.HTTPError as error:
                attempts.append({
                    "scheme": scheme,
                    "port": port,
                    "path": path,
                    "status": error.code,
                    "authenticated": False,
                })
            except Exception as error:
                attempts.append({
                    "scheme": scheme,
                    "port": port,
                    "path": path,
                    "error": type(error).__name__,
                    "authenticated": False,
                })

    return {
        "supported": bool(attempts),
        "authenticated": any(item.get("authenticated") for item in attempts),
        "attempts": attempts,
    }


def v111_rtsp_verify(device_ip: str, username: str, password: str) -> dict:
    import base64
    import socket

    authorization = base64.b64encode(
        f"{username}:{password}".encode("utf-8")
    ).decode("ascii")
    request = (
        f"OPTIONS rtsp://{device_ip}:554/ RTSP/1.0\r\n"
        f"CSeq: 1\r\n"
        f"User-Agent: AnyAiCam-VMS/1.1.1\r\n"
        f"Authorization: Basic {authorization}\r\n\r\n"
    ).encode("ascii", errors="ignore")

    try:
        with socket.create_connection((device_ip, 554), timeout=3) as connection:
            connection.sendall(request)
            response = connection.recv(4096).decode("latin-1", errors="replace")
        first_line = response.splitlines()[0] if response else ""
        status_code = None
        parts = first_line.split()
        if len(parts) >= 2 and parts[1].isdigit():
            status_code = int(parts[1])
        return {
            "supported": bool(first_line.startswith("RTSP/")),
            "authenticated": status_code is not None and 200 <= status_code < 300,
            "status_code": status_code,
            "server": next(
                (
                    line.split(":", 1)[1].strip()
                    for line in response.splitlines()
                    if line.lower().startswith("server:")
                ),
                "",
            ),
        }
    except Exception as error:
        return {
            "supported": False,
            "authenticated": False,
            "error": type(error).__name__,
        }


def v111_onvif_verify(device_ip: str, username: str, password: str) -> dict:
    import base64
    import urllib.error
    import urllib.request

    credentials = base64.b64encode(
        f"{username}:{password}".encode("utf-8")
    ).decode("ascii")
    url = f"http://{device_ip}/onvif/device_service"
    request = urllib.request.Request(
        url,
        headers={
            "Authorization": f"Basic {credentials}",
            "Content-Type": "application/soap+xml; charset=utf-8",
            "User-Agent": "AnyAiCam-VMS/1.1.1",
        },
        data=(
            b'<?xml version="1.0" encoding="UTF-8"?>'
            b'<s:Envelope xmlns:s="http://www.w3.org/2003/05/soap-envelope">'
            b'<s:Body><GetSystemDateAndTime xmlns="http://www.onvif.org/ver10/device/wsdl"/>'
            b'</s:Body></s:Envelope>'
        ),
        method="POST",
    )
    try:
        with urllib.request.urlopen(request, timeout=3) as response:
            body = response.read(8192)
            return {
                "supported": response.status == 200,
                "authenticated": response.status == 200,
                "status_code": response.status,
                "response_length": len(body),
            }
    except urllib.error.HTTPError as error:
        return {
            "supported": error.code in {200, 400, 401, 403, 405, 500},
            "authenticated": error.code == 200,
            "status_code": error.code,
        }
    except Exception as error:
        return {
            "supported": False,
            "authenticated": False,
            "error": type(error).__name__,
        }


@app.post("/api/camera-verification/verify")
def v111_verify_camera(payload: V111VerifyModel, request: Request) -> dict:
    user = current_user(request)
    if not has_permission(user, "manage_settings"):
        raise HTTPException(status_code=403, detail="Settings permission is required.")
    if not payload.consent_confirmed:
        raise HTTPException(
            status_code=400,
            detail="Explicit authorization is required before authentication.",
        )

    import ipaddress
    try:
        selected_ip = ipaddress.ip_address(payload.selected_device_ip.strip())
    except ValueError as exc:
        raise HTTPException(status_code=400, detail="Invalid device IP address.") from exc
    if not selected_ip.is_private:
        raise HTTPException(
            status_code=400,
            detail="Only private local-network device addresses are allowed.",
        )

    session = V110_CREDENTIAL_SESSIONS.get(payload.session_token)
    if not session:
        raise HTTPException(
            status_code=404,
            detail="Credential session not found or expired.",
        )
    if session.get("site_id") != payload.site_id.strip():
        raise HTTPException(status_code=409, detail="Credential session site mismatch.")
    if session.get("device_ip") != str(selected_ip):
        raise HTTPException(status_code=409, detail="Credential session device mismatch.")

    v111_check_rate_limit(str(selected_ip))

    username = session["username"]
    password = session["password"]

    results = {
        "http": (
            v111_http_verify(str(selected_ip), username, password)
            if payload.test_http
            else {"skipped": True}
        ),
        "rtsp": (
            v111_rtsp_verify(str(selected_ip), username, password)
            if payload.test_rtsp
            else {"skipped": True}
        ),
        "onvif": (
            v111_onvif_verify(str(selected_ip), username, password)
            if payload.test_onvif
            else {"skipped": True}
        ),
    }

    authenticated_protocols = [
        protocol
        for protocol, result in results.items()
        if result.get("authenticated") is True
    ]
    supported_protocols = [
        protocol
        for protocol, result in results.items()
        if result.get("supported") is True
    ]

    record = {
        "id": uuid.uuid4().hex[:16],
        "site_id": payload.site_id.strip(),
        "device_ip": str(selected_ip),
        "verified_at": datetime.now().isoformat(),
        "verified_by": user.get("id", "unknown"),
        "supported_protocols": supported_protocols,
        "authenticated_protocols": authenticated_protocols,
        "credential_valid": bool(authenticated_protocols),
        "results": results,
        "username_present": bool(username),
        "password_present": bool(password),
        "username_value_stored": False,
        "password_value_stored": False,
        "credential_session_persisted": False,
    }

    records = _v111_load(V111_VERIFICATION_FILE, [])
    records.append(record)
    _v111_save(V111_VERIFICATION_FILE, records[-5000:])

    structured_log(
        "v111.camera_verified",
        site_id=record["site_id"],
        device_ip=record["device_ip"],
        credential_valid=record["credential_valid"],
        supported_protocols=supported_protocols,
        authenticated_protocols=authenticated_protocols,
        actor=user.get("id", "unknown"),
    )

    return record


@app.get("/api/camera-verification/history")
def v111_verification_history(request: Request) -> dict:
    user = current_user(request)
    if not has_permission(user, "manage_settings"):
        raise HTTPException(status_code=403, detail="Settings permission is required.")
    records = _v111_load(V111_VERIFICATION_FILE, [])
    return {"history": list(reversed(records[-200:]))}


@app.get("/camera-verification", response_class=HTMLResponse)
def v111_camera_verification_page(request: Request):
    user = current_user(request)
    if not has_permission(user, "manage_settings"):
        raise HTTPException(status_code=403, detail="Settings permission is required.")

    content = """
    <header class="topbar">
      <div>
        <p class="eyebrow">AnyAiCam VMS v1.1.1</p>
        <h1>Camera verification</h1>
      </div>
      <span class="pill">Explicit authentication</span>
    </header>

    <section class="panel">
      <div class="panel-head">
        <div>
          <h2>Verify one selected camera or recorder</h2>
          <div class="health-detail">
            Uses an existing temporary credential session. One explicit attempt
            is made against the selected private-network device. Passwords and
            usernames are never saved in verification records or logs.
          </div>
        </div>
      </div>

      <form id="v111-form" class="settings-grid">
        <label>Site ID<input id="v111-site" required></label>
        <label>Selected device IP<input id="v111-ip" required placeholder="192.168.1.25"></label>
        <label>Credential session token<input id="v111-token" required autocomplete="off"></label>

        <label><input id="v111-http" type="checkbox" checked> Verify HTTP/HTTPS</label>
        <label><input id="v111-rtsp" type="checkbox" checked> Verify RTSP</label>
        <label><input id="v111-onvif" type="checkbox" checked> Verify ONVIF</label>

        <label>
          <input id="v111-consent" type="checkbox" required>
          I confirm authorization to authenticate to this selected device.
        </label>

        <div><button class="action-button" type="submit">Verify selected device</button></div>
      </form>

      <pre id="v111-output" style="white-space:pre-wrap;margin-top:16px"></pre>
    </section>
    """

    scripts = """
    <script>
    document.getElementById('v111-form').onsubmit=async event=>{
      event.preventDefault();
      const payload={
        site_id:document.getElementById('v111-site').value.trim(),
        selected_device_ip:document.getElementById('v111-ip').value.trim(),
        session_token:document.getElementById('v111-token').value.trim(),
        consent_confirmed:document.getElementById('v111-consent').checked,
        test_http:document.getElementById('v111-http').checked,
        test_rtsp:document.getElementById('v111-rtsp').checked,
        test_onvif:document.getElementById('v111-onvif').checked
      };
      const response=await fetch('/api/camera-verification/verify',{
        method:'POST',
        headers:{'Content-Type':'application/json'},
        body:JSON.stringify(payload)
      });
      const data=await response.json();
      document.getElementById('v111-output').textContent=JSON.stringify(data,null,2);
      if(!response.ok) showToast(data.detail||'Camera verification failed.');
    };
    </script>
    """
    return page_shell("Camera verification", "settings", content, scripts)
